INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بِسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبَائِثِ$q$, $q$Bismi llahi, Allahoumma inni aʿoudhou bika mina l-khoubthi wal-khaba’ith$q$, $q$Au nom d’Allah. Ô Allah, je cherche refuge auprès de Toi contre les démons mâles et femelles.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr en entrant aux toilettes », invocation n° 1. Al-Bukhari 1/45 ; Muslim 1/283 (hadith unanimement reconnu). L’ajout « Au nom d’Allah » au début est rapporté par Sa‘id ibn Mansur (voir Fath al-Bari 1/244).$q$, 1, 200, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بِسْمِ اللَّهِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْخُبْثِ وَالْخَبَائِثِ$q$);

