WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$غُفْرَانَكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بِسْمِ اللَّهِ$q$, $q$Bismi llah$q$, $q$Au nom d’Allah. (avant les ablutions ; la même formule se dit en ôtant son vêtement et avant de manger : si on l’oublie au début du repas, dire « Au nom d’Allah, au début et à la fin »)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr avant les ablutions (aussi en ôtant son vêtement et avant le repas) », invocation n° 1. Ablutions : Abu Dawud, Ibn Majah, Ahmad (voir Irwa’ al-ghalil 1/122). Vêtement ôté : at-Tirmidhi 2/505 et d’autres (Irwa’ n° 49) : écran entre les yeux des djinns et la nudité des fils d’Adam. Repas : Abu Dawud 3/347 ; at-Tirmidhi 4/288.$q$, 1, 202, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بِسْمِ اللَّهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ$q$, $q$Achhadou an la ilaha illa llahou wahdahou la charika lahou wa’achhadou anna mouhammadan ʿabdouhou warasoulouh$q$, $q$J’atteste qu’il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé, et j’atteste que Muhammad est Son serviteur et Son messager.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après les ablutions (le n° 3 conclut aussi une assemblée) », invocation n° 1. Muslim 1/209.$q$, 1, 203, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ$q$, $q$Allahoumma-djʿalni mina t-tawwabina wadjʿalni mina l-moutatahhirin$q$, $q$Ô Allah, fais de moi l’un de ceux qui reviennent à Toi avec repentir et l’un de ceux qui se purifient. (à ajouter après les deux témoignages)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après les ablutions (le n° 3 conclut aussi une assemblée) », invocation n° 2. At-Tirmidhi 1/78 (voir Sahih at-Tirmidhi 1/18). C’est un ajout rapporté par at-Tirmidhi après les deux témoignages.$q$, 1, 204, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ اجْعَلْنِي مِنَ التَّوَّابِينَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِينَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ$q$, $q$Soubhanaka llahoumma wabihamdika, achhadou an la ilaha illa anta, astaghfirouka wa’atoubou ilayk$q$, $q$Gloire et pureté à Toi, ô Allah, et louange à Toi. J’atteste qu’il n’y a de divinité digne d’adoration que Toi ; je Te demande pardon et je me repens auprès de Toi. (après les ablutions ; la même formule conclut une assemblée)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après les ablutions (le n° 3 conclut aussi une assemblée) », invocation n° 3. Ablutions : an-Nasa’i, ‘Amal al-yawm wa-l-layla p. 173 (Irwa’ al-ghalil 1/135 et 2/94). Fin d’assemblée : les auteurs des Sunan (Sahih at-Tirmidhi 3/153) ; ‘A’isha : le Messager d’Allah concluait ainsi toute assemblée, récitation ou prière (an-Nasa’i n° 308 ; Ahmad 6/77).$q$, 1, 205, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلاَ حَوْلَ وَلَا قُوَّةَ إِلاَّ بِاللَّهِ$q$, $q$Bismi llahi, tawakkaltou ʿala llahi, wala hawla wala qouwwata illa billah$q$, $q$Au nom d’Allah ; je m’en remets à Allah ; il n’y a de force ni de puissance qu’en Allah.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr en sortant de la maison », invocation n° 1. Abu Dawud 4/325 ; at-Tirmidhi 5/490 (voir Sahih at-Tirmidhi 3/151).$q$, 1, 206, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلاَ حَوْلَ وَلَا قُوَّةَ إِلاَّ بِاللَّهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضَلَّ، أَوْ أَزِلَّ، أَوْ أُزَلَّ، أَوْ أَظْلِمَ، أَوْ أُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ$q$, $q$Allahoumma inni aʿoudhou bika an adilla, aw oudalla, aw azilla, aw ouzalla, aw adhlima, aw oudhlama, aw adjhala, aw youdjhala ʿalayya$q$, $q$Ô Allah, je cherche refuge auprès de Toi pour ne pas m’égarer ni être égaré, pour ne pas faillir ni être poussé à faillir, pour ne pas être injuste ni victime d’une injustice, pour ne pas être ignorant ni qu’on se montre ignorant envers moi.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr en sortant de la maison », invocation n° 2. Les auteurs des Sunan (voir Sahih at-Tirmidhi 3/152 ; Sahih Ibn Majah 2/336).$q$, 1, 207, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضَلَّ، أَوْ أَزِلَّ، أَوْ أُزَلَّ، أَوْ أَظْلِمَ، أَوْ أُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا$q$, $q$Bismi llahi waladjna, wabismi llahi kharadjna, waʿala llahi rabbina tawakkalna$q$, $q$Au nom d’Allah nous sommes entrés, au nom d’Allah nous sommes sortis, et c’est en Allah, notre Seigneur, que nous plaçons notre confiance. (puis saluer les siens)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr en entrant à la maison », invocation n° 1. Abu Dawud 4/325 ; Ibn Baz a jugé sa chaîne hassan (Tuhfat al-akhyar p. 28). Hadith authentique : quand l’homme entre chez lui et mentionne Allah à son entrée et à son repas, Satan dit : « Pas de gîte ni de dîner pour vous » (Muslim n° 2018).$q$, 1, 208, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُوراً، وَفِي لِسَانِي نُوراً، وَفِي سَمْعِي نُوراً، وَفِي بَصَرِي نُوراً، وَمِنْ فَوْقِي نُوراً، وَمِنْ تَحْتِي نُوراً، وَعَنْ يَمِينِي نُوراً، وَعَنْ شِمَالِي نُوراً، وَمِنْ أَمَامِي نُوراً، وَمِنْ خَلْفِي نُوراً، وَاجْعَلْ فِي نَفْسِي نُوراً، وَأَعْظِمْ لِي نُوراً، وَعَظِّم لِي نُوراً، وَاجْعَلْ لِي نُوراً، وَاجْعَلْنِي نُوراً، اللَّهُمَّ أَعْطِنِي نُوراً، وَاجْعَلْ فِي عَصَبِي نُوراً، وَفِي لَحْمِي نُوراً، وَفِي دَمِي نُوراً، وَفِي شَعْرِي نُوراً، وَفِي بَشَرِي نُوراً$q$, $q$Allahoumma-djʿal fi qalbi nouran, wafi lisani nouran, wafi samʿi nouran, wafi basari nouran, wamin fawqi nouran, wamin tahti nouran, waʿan yamini nouran, waʿan chimali nouran, wamin amami nouran, wamin khalfi nouran, wadjʿal fi nafsi nouran, wa’aʿdhim li nouran, waʿadhdhim li nouran, wadjʿal li nouran, wadjʿalni nouran, Allahoumma aʿtini nouran, wadjʿal fi ʿasabi nouran, wafi lahmi nouran, wafi dami nouran, wafi chaʿri nouran, wafi bachari noura$q$, $q$Ô Allah, place une lumière dans mon cœur, une lumière dans ma langue, une lumière dans mon ouïe, une lumière dans ma vue, une lumière au-dessus de moi, une lumière au-dessous de moi, une lumière à ma droite, une lumière à ma gauche, une lumière devant moi, une lumière derrière moi ; place une lumière dans mon âme, agrandis ma lumière, rends-la immense pour moi, accorde-moi une lumière, fais de moi une lumière. Ô Allah, donne-moi une lumière ; place une lumière dans mes nerfs, dans ma chair, dans mon sang, dans mes cheveux et dans ma peau.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation en allant à la mosquée », invocation n° 1. Al-Bukhari 11/116 n° 6316 ; Muslim 1/526, 529, 530 n° 763 (toutes ces demandes y figurent). Les autres renvois du recueil concernent des ajouts que nous n’avons pas repris (lumière dans la tombe et les os, « accorde-moi une lumière sur une lumière »).$q$, 1, 209, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُوراً، وَفِي لِسَانِي نُوراً، وَفِي سَمْعِي نُوراً، وَفِي بَصَرِي نُوراً، وَمِنْ فَوْقِي نُوراً، وَمِنْ تَحْتِي نُوراً، وَعَنْ يَمِينِي نُوراً، وَعَنْ شِمَالِي نُوراً، وَمِنْ أَمَامِي نُوراً، وَمِنْ خَلْفِي نُوراً، وَاجْعَلْ فِي نَفْسِي نُوراً، وَأَعْظِمْ لِي نُوراً، وَعَظِّم لِي نُوراً، وَاجْعَلْ لِي نُوراً، وَاجْعَلْنِي نُوراً، اللَّهُمَّ أَعْطِنِي نُوراً، وَاجْعَلْ فِي عَصَبِي نُوراً، وَفِي لَحْمِي نُوراً، وَفِي دَمِي نُوراً، وَفِي شَعْرِي نُوراً، وَفِي بَشَرِي نُوراً$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ$q$, $q$Aʿoudhou billahi l-ʿadhimi, wabiwadjhihi l-karimi, wasoultanihi l-qadimi, mina ch-chaytani r-radjimi, bismi llahi, was-salatou was-salamou ʿala rasouli llahi, Allahoumma-ftah li abwaba rahmatik$q$, $q$(Entrer du pied droit.) Je cherche refuge auprès d’Allah le Très-Grand, par Son noble Visage et Sa souveraineté éternelle, contre Satan le maudit. Au nom d’Allah, et que la prière et la paix soient sur le Messager d’Allah. Ô Allah, ouvre-moi les portes de Ta miséricorde.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation en entrant à la mosquée », invocation n° 1. Renvois du recueil (rattachement non précisé) : Abu Dawud (voir Sahih al-Jami‘ n° 4591) ; Ibn as-Sunni n° 88, jugé hassan par al-Albani ; Abu Dawud 1/126 (Sahih al-Jami‘ 1/528) ; Muslim 1/494 (Ibn Majah, d’après Fatima : « Ô Allah, pardonne-moi mes péchés et ouvre-moi les portes de Ta miséricorde », jugé sahih par al-Albani grâce à ses témoins).$q$, 1, 210, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَعُوذُ بِاللَّهِ الْعَظِيمِ، وَبِوَجْهِهِ الْكَرِيمِ، وَسُلْطَانِهِ الْقَدِيمِ، مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ$q$, $q$Bismi llahi was-salatou was-salamou ʿala rasouli llahi, Allahoumma inni as’alouka min fadlika, Allahoumma-ʿsimni mina ch-chaytani r-radjim$q$, $q$(Sortir du pied gauche.) Au nom d’Allah, et que la prière et la paix soient sur le Messager d’Allah. Ô Allah, je Te demande de Ta grâce. Ô Allah, protège-moi de Satan le maudit.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation en sortant de la mosquée », invocation n° 1. Voir les renvois de l’invocation précédente. L’ajout « Ô Allah, protège-moi de Satan le maudit » est rapporté par Ibn Majah (voir Sahih Ibn Majah 1/288).$q$, 1, 211, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللَّهِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ$q$, $q$Al-hamdou lillahi-lladhi kasani hadha warazaqanihi min ghayri hawlin minni wala qouwwah$q$, $q$Louange à Allah qui m’a vêtu de ceci et me l’a accordé sans force ni puissance de ma part.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation en mettant un vêtement », invocation n° 1. Les auteurs des Sunan, sauf an-Nasa’i (voir Irwa’ al-ghalil 7/47).$q$, 1, 212, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ$q$, $q$Allahoumma laka l-hamdou anta kasawtanihi, as’alouka min khayrihi wakhayri ma souniʿa lahou, wa’aʿoudhou bika min charrihi wacharri ma souniʿa lah$q$, $q$Ô Allah, à Toi la louange, c’est Toi qui me l’as fait porter. Je Te demande son bien et le bien de ce pour quoi il a été fait, et je cherche refuge auprès de Toi contre son mal et le mal de ce pour quoi il a été fait.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation en mettant un vêtement neuf », invocation n° 1. Abu Dawud, at-Tirmidhi, al-Baghawi (voir Mukhtasar ash-Shama’il d’at-Tirmidhi par al-Albani p. 47).$q$, 1, 213, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اِلْبَسْ جَدِيداً وَعِشْ حَمِيداً وَمُتْ شَهِيداً$q$, $q$Ilbas djadidan waʿich hamidan wamout chahida$q$, $q$Porte du neuf, vis digne de louange et meurs en martyr. (à dire à celui qui porte un vêtement neuf)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation pour celui qui porte un vêtement neuf », invocation n° 1. Ibn Majah 2/1178 ; al-Baghawi 12/41 (voir Sahih Ibn Majah 2/275).$q$, 1, 214, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اِلْبَسْ جَدِيداً وَعِشْ حَمِيداً وَمُتْ شَهِيداً$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالَى$q$, $q$Toubli wayoukhlifou llahou taʿala$q$, $q$Puisses-tu l’user, et qu’Allah, le Très-Haut, te le remplace. (à dire à celui qui porte un vêtement neuf)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation pour celui qui porte un vêtement neuf », invocation n° 2. Abu Dawud 4/41 (voir Sahih Abi Dawud 2/760).$q$, 1, 215, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالَى$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْراً مِنْهُ$q$, $q$Allahoumma barik lana fihi wa’atʿimna khayran minh$q$, $q$Ô Allah, bénis-nous ce repas et donne-nous mieux que cela à manger. (à dire pour une nourriture qu’Allah nous a donnée)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation avant le repas », invocation n° 1. At-Tirmidhi 5/506 (voir Sahih at-Tirmidhi 3/158).$q$, 1, 216, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْراً مِنْهُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ$q$, $q$Allahoumma barik lana fihi wazidna minh$q$, $q$Ô Allah, bénis-le pour nous et accorde-nous-en davantage. (à dire quand on a bu du lait)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation avant le repas », invocation n° 2. At-Tirmidhi 5/506 (voir Sahih at-Tirmidhi 3/158).$q$, 1, 217, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ$q$, $q$Al-hamdou lillahi-lladhi atʿamani hadha, warazaqanihi, min ghayri hawlin minni wala qouwwah$q$, $q$Louange à Allah qui m’a nourri de ceci et me l’a accordé sans force ni puissance de ma part.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation après le repas », invocation n° 1. Les auteurs des Sunan, sauf an-Nasa’i (voir Sahih at-Tirmidhi 3/159).$q$, 1, 218, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا، وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$الْحَمْدُ لِلَّهِ حَمْداً كَثِيراً طَيِّباً مُبَارَكاً فِيهِ، غَيْرَ مَكْفِيٍّ وَلاَ مُوَدَّعٍ، وَلاَ مُسْتَغْنَىً عَنْهُ رَبَّنَا$q$, $q$Al-hamdou lillahi hamdan kathiran tayyiban moubarakan fihi, ghayra makfiyyin wala mouwaddaʿin, wala moustaghnan ʿanhou rabbana$q$, $q$Louange à Allah, une louange abondante, bonne et bénie, (pour une nourriture) dont on ne peut se passer, qu’on ne peut délaisser et dont on ne peut se dispenser, ô notre Seigneur.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation après le repas », invocation n° 2. Al-Bukhari 6/214 ; at-Tirmidhi, avec ce texte, 5/507.$q$, 1, 219, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$الْحَمْدُ لِلَّهِ حَمْداً كَثِيراً طَيِّباً مُبَارَكاً فِيهِ، غَيْرَ مَكْفِيٍّ وَلاَ مُوَدَّعٍ، وَلاَ مُسْتَغْنَىً عَنْهُ رَبَّنَا$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُم، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ$q$, $q$Allahoumma barik lahoum fima razaqtahoum, waghfir lahoum warhamhoum$q$, $q$Ô Allah, bénis-les dans ce que Tu leur as accordé, pardonne-leur et fais-leur miséricorde.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation de l’invité pour son hôte », invocation n° 1. Muslim 3/1626.$q$, 1, 220, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ بَارِكْ لَهُمْ فِيمَا رَزَقْتَهُم، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لاَ يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou, walahou l-hamdou, youhyi wayoumitou, wahouwa hayyoun la yamoutou, biyadihi l-khayrou, wahouwa ʿala koulli chay’in qadir$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté et la louange ; Il donne la vie et la mort, et Il est Vivant et ne meurt pas. Le bien est dans Sa main, et Il est Omnipotent.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Invocation en entrant au marché », invocation n° 1. At-Tirmidhi 5/491 ; al-Hakim 1/538 ; jugé hassan par al-Albani (Sahih Ibn Majah 2/21 ; Sahih at-Tirmidhi 3/152).$q$, 1, 221, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لاَ يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ$q$, $q$Rabbi-ghfir li, watoub ʿalayya, innaka anta t-tawwabou l-ghafour$q$, $q$Seigneur, pardonne-moi et accepte mon repentir, car Tu es Celui qui accepte le repentir, le Pardonneur. (Ibn ‘Umar rapporte qu’on comptait pour le Messager d’Allah cent fois cette invocation dans une même assemblée, avant qu’il ne se lève.)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Ce que l’on dit pendant une assemblée », invocation n° 1. At-Tirmidhi et d’autres (voir Sahih at-Tirmidhi 3/153 ; Sahih Ibn Majah 2/321) ; le texte est celui d’at-Tirmidhi.$q$, 1, 222, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ$q$);
